// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 value1, uint256 value2) public {
        value1 = bound(value1, 1, 1e36);
        value2 = bound(value2, 1, 1e36);

        address caller = address(0x1234);
        vm.deal(caller, value1 + value2);

        vm.prank(caller);
        (bool ok1, ) = address(c).call{value: value1}("");
        require(ok1, "first receive failed");

        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: value2}("");
        require(ok2, "second receive failed");

        assertTrue(c.depositsCount() == 2);
    }
}
